import csv
from collections.abc import Iterable
from typing import TextIO

COLUMNS = ["date", "payment_ref", "amount", "partner_name", "ref", "transaction_type",
           "narration", "unique_import_id"]

# Free text from the bank. date, amount and the id are generated by us, so they are left alone.
_TEXT = ("payment_ref", "partner_name", "ref", "transaction_type", "narration")
_FORMULA_START = ("=", "+", "-", "@", "\t", "\r", "＝", "＋", "－", "＠")  # last four: full-width


def _cell(text: str) -> str:
    """A chunk starting with = + - @ (after spaces) runs as a formula in Excel; a leading ' makes it text.
    Chunks split on ';' too: Excel with a Spanish locale treats ';' as the cell separator."""
    return ";".join("'" + c if c.lstrip(" ").startswith(_FORMULA_START) else c for c in text.split(";"))


def _safe(row: dict[str, str]) -> dict[str, str]:
    return {k: _cell(v) if k in _TEXT else v for k, v in row.items()}


def write_csv(rows: Iterable[dict[str, str]], fp: TextIO, *, journal: str, unique_id: bool = True) -> None:
    """Write Odoo-importer CSV. The journal is mandatory: without journal_id Odoo 18 files the
    lines under the company's first bank/cash journal without a warning."""
    if not journal.strip():
        raise ValueError("a journal name is required")
    columns = [c for c in COLUMNS if unique_id or c != "unique_import_id"] + ["journal_id"]
    writer = csv.DictWriter(fp, fieldnames=columns, extrasaction="ignore", lineterminator="\n")
    writer.writeheader()
    for row in rows:
        writer.writerow({**_safe(row), "journal_id": journal})
